package models

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
	"rep-1/internal/models"
)

// In-memory storage for users
var (
	users = make(map[string]models.User)
	mutex sync.RWMutex
)

// GetAllUsers returns a list of all users
func GetAllUsers() []models.User {
	mutex.RLock()
	defer mutex.RUnlock()
	var list []models.User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and adds it to the storage
func CreateUser(user models.User) (models.User, error) {
	mutex.Lock()
	defer mutex.Unlock()

	user.ID = uuid.New().String()
	users[user.ID] = user
	return user, nil
}

// GetUserByID returns a user by their ID
func GetUserByID(id string) (models.User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()
	user, ok := users[id]
	return user, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"rep-1/internal/models"
	"rep-1/internal/service"
)

// GetUsersHandler handles GET requests for all users and POST requests for creating new users
func GetUsersHandler(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		list := service.GetAllUsers()
		json.NewEncoder(w).Encode(list)

	case http.MethodPost:
		var u models.User
		if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		createdUser, err := service.CreateUser(u)
		if err != nil {
			http.Error(w, err.Error(), http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(createdUser)

	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// GetUserByIDHandler handles GET requests for a single user by ID
func GetUserByIDHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]

	switch r.Method {
	case http.MethodGet:
		u, ok := service.GetUserByID(id)
		if !ok {
			http.NotFound(w, r)
			return
		}
		json.NewEncoder(w).Encode(u)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

package main

import (
	"log"
	"net/http"

	"rep-1/internal/api"
)

func main() {
	http.HandleFunc("/users", api.GetUsersHandler)
	http.HandleFunc("/users/", api.GetUserByIDHandler)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"testing"

	"rep-1/internal/models"
)

func TestCreateAndGetUsers(t *testing.T) {
	// Clear existing users for a clean test environment
	users = make(map[string]models.User)

	// Test CreateUser
	user1 := models.User{Name: "Alice", Email: "alice@example.com"}
	createdUser1, err := CreateUser(user1)
	if err != nil {
		t.Fatalf("CreateUser failed: %v", err)
	}
	if createdUser1.ID == "" {
		t.Error("Expected user ID to be generated, got empty")
	}
	if createdUser1.Name != user1.Name || createdUser1.Email != user1.Email {
		t.Errorf("Created user mismatch. Expected %+v, got %+v", user1, createdUser1)
	}

	user2 := models.User{Name: "Bob", Email: "bob@example.com"}
	createdUser2, err := CreateUser(user2)
	if err != nil {
		t.Fatalf("CreateUser failed: %v", err)
	}

	// Test GetAllUsers
	allUsers := GetAllUsers()
	if len(allUsers) != 2 {
		t.Errorf("Expected 2 users, got %d", len(allUsers))
	}

	// Test GetUserByID
	fetchedUser1, ok := GetUserByID(createdUser1.ID)
	if !ok {
		t.Errorf("Expected to find user with ID %s, but not found", createdUser1.ID)
	}
	if fetchedUser1.Name != user1.Name {
		t.Errorf("Fetched user by ID mismatch. Expected name %s, got %s", user1.Name, fetchedUser1.Name)
	}

	_, ok = GetUserByID("nonexistent-id")
	if ok {
		t.Error("Expected not to find a nonexistent user, but found one")
	}
}
